import React, {useContext, useState, useEffect} from "react";
import {Fade} from "react-reveal";
import "./Greeting.scss";
import NeuralNetworkSVG from "../../components/NeuralNetworkSVG/NeuralNetworkSVG";
import SocialMedia from "../../components/socialMedia/SocialMedia";
import ParticleBackground from "../../components/ParticleBackground/ParticleBackground";
import {illustration, greeting, resumeSection} from "../../portfolio";
import StyleContext from "../../contexts/StyleContext";

export default function Greeting() {
  const {isDark} = useContext(StyleContext);
  const [titleIndex, setTitleIndex] = useState(0);
  const [fadeClass, setFadeClass] = useState("fade-in");

  // Rotating typewriter: cycle through greeting.titles every 3500ms
  useEffect(() => {
    if (!greeting.titles || greeting.titles.length <= 1) return;
    const interval = setInterval(() => {
      setFadeClass("fade-out");
      setTimeout(() => {
        setTitleIndex((prev) => (prev + 1) % greeting.titles.length);
        setFadeClass("fade-in");
      }, 200);
    }, 3500);
    return () => clearInterval(interval);
  }, []);

  if (!greeting.displayGreeting) {
    return null;
  }

  const currentTitle =
    greeting.titles && greeting.titles.length > 0
      ? greeting.titles[titleIndex]
      : "I Build Intelligent Systems with Data";

  return (
    <Fade bottom duration={1000} distance="40px">
      <div className="greet-main" id="greeting" style={{position: "relative"}}>
        {/* Floating Particles Background */}
        <ParticleBackground isDark={isDark} />

        <div className="greeting-main" style={{position: "relative", zIndex: 1}}>
          <div className="greeting-text-div">
            <div>
              {/* 1. Status badge */}
              <div className={isDark ? "dark-mode internship-badge" : "internship-badge"}>
                <span className="internship-dot"></span>
                🎯 {greeting.availabilityBadge || "Available for Internships"}
              </div>

              {/* 2. Rotating headline */}
              <h1
                className={
                  isDark
                    ? `dark-mode greeting-text fade-title ${fadeClass}`
                    : `greeting-text fade-title ${fadeClass}`
                }
              >
                {currentTitle}
              </h1>

              {/* 3. Subheading paragraph */}
              <p
                className={
                  isDark
                    ? "dark-mode greeting-text-p"
                    : "greeting-text-p subTitle"
                }
              >
                {greeting.subTitle}
              </p>

              {/* 4. Social proof anchor line */}
              <p className="greeting-social-proof">
                IIT Hyderabad Certified &nbsp;·&nbsp; SSIP Cell Recognized &nbsp;·&nbsp; CodSoft ISO 9001:2015 Verified
              </p>

              {/* 5. Bullet achievement list */}
              {greeting.proofPoints && greeting.proofPoints.length > 0 && (
                <ul className={isDark ? "dark-mode proof-points" : "proof-points"}>
                  {greeting.proofPoints.map((point, i) => (
                    <li key={i} className="proof-point-item">
                      <i className="fas fa-check-circle proof-icon"></i>
                      <span>{point}</span>
                    </li>
                  ))}
                </ul>
              )}

              {/* 6. CTA Buttons row — 3-tier hierarchy */}
              <div className="button-greeting-div">
                <a href="#projects" className="cta-link">
                  <button className={isDark ? "dark-mode cta-button cta-primary" : "cta-button cta-primary"}>
                    <i className="fas fa-rocket"></i> View Projects
                  </button>
                </a>
                {greeting.resumeLink && (
                  <a
                    href={resumeSection.resumeLink}
                    download="Vishvrajsinh_Solanki_Resume.pdf"
                    className="cta-link"
                  >
                    <button className={isDark ? "dark-mode cta-button cta-secondary" : "cta-button cta-secondary"}>
                      <i className="fas fa-file-download"></i> Download Resume
                    </button>
                  </a>
                )}
                <a href="#contact" className="cta-link">
                  <button className={isDark ? "dark-mode cta-button cta-tertiary" : "cta-button cta-tertiary"}>
                    <i className="fas fa-paper-plane"></i> Contact Me
                  </button>
                </a>
              </div>

              {/* 7. Social media icons row */}
              <div className="greeting-social-div">
                <SocialMedia />
              </div>

              {/* 8. Proof Stats — Metric Cards */}
              {greeting.proofStats && (
                <div className="proof-stats-row">
                  {greeting.proofStats.map((stat, i) => (
                    <div className="proof-stat-card" key={i}>
                      <i className={`${stat.icon} stat-icon`}></i>
                      <div>
                        <div className="stat-value">{stat.value}</div>
                        <div className="stat-label">{stat.label}</div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
          <div className="greeting-image-div">
            {/* 9. Neural Network SVG replaces old Lottie */}
            <div className="hero-lottie-wrapper">
              <NeuralNetworkSVG />
            </div>
          </div>
        </div>
      </div>
    </Fade>
  );
}
