import React, { useState, useContext } from "react";
import "./StartupProjects.scss";
import { bigProjects as portfolioBigProjects } from "../../portfolio";
import StyleContext from "../../contexts/StyleContext";
import TrackBotFlow from "../../components/TrackBotFlow/TrackBotFlow";

/* ─── Image carousel sub-component ─────────────────────────────────── */
function ProjectImageCarousel({ images, projectName, onImageClick }) {
  const [active, setActive] = useState(0);
  if (!images || images.length === 0) return null;

  // Determine a matching background color and fit mode to prevent cropping of dashboards and blueprints
  let bgColor = "transparent";
  let fitMode = "cover";
  
  if (projectName.includes("Lexis")) {
    bgColor = "#fcf9f2"; // Solar paper warm light cream
    fitMode = "contain";
  } else if (projectName.includes("RupeeIQ")) {
    bgColor = "#0d1117"; // Terminal black/dark
    fitMode = "contain";
  } else if (projectName.includes("TrackBot")) {
    bgColor = "#faf8f5"; // Clean technical card white
    fitMode = "contain";
  }

  return (
    <div 
      className="bento-carousel" 
      role="region" 
      aria-label={`${projectName} screenshots`}
      style={{ backgroundColor: bgColor, height: "100%", width: "100%" }}
    >
      <img
        src={images[active].src}
        alt={images[active].alt}
        className="bento-carousel__img"
        loading="lazy"
        onClick={() => onImageClick && onImageClick(images[active])}
        style={{ 
          cursor: onImageClick ? "zoom-in" : "default",
          objectFit: fitMode,
          padding: fitMode === "contain" ? "12px" : "0",
          width: "100%",
          height: "100%"
        }}
      />
      {images.length > 1 && (
        <div className="bento-carousel__dots" aria-hidden="true">
          {images.map((_, i) => (
            <button
              key={i}
              className={`bento-carousel__dot${i === active ? " is-active" : ""}`}
              onClick={() => setActive(i)}
              aria-label={`Show screenshot ${i + 1}`}
            />
          ))}
        </div>
      )}
    </div>
  );
}

/* ─── Featured card (Lexis) — horizontal split ──────────────────────── */
function FeaturedCard({ project, onImageClick }) {
  return (
    <article className="bento-card bento-card--featured" aria-label={`Featured project: ${project.projectName}`}>
      <div className="bento-card--featured__inner">

        {/* LEFT: text content */}
        <div className="bento-card--featured__text">
          <span className="bento-badge" aria-label="Featured project">
            Featured project
          </span>
          <h3 className="bento-project-title">{project.projectName}</h3>
          <p className="bento-highlight">{project.highlightLine}</p>

          {project.keyFeatures && project.keyFeatures.length > 0 && (
            <ul className="bento-features" aria-label="Key features">
              {project.keyFeatures.slice(0, 3).map((f, i) => (
                <li key={i} className="bento-features__item">{f}</li>
              ))}
            </ul>
          )}

          {project.techStack && project.techStack.length > 0 && (
            <div className="bento-tags" aria-label="Tech stack">
              {project.techStack.slice(0, 8).map((tech, i) => (
                <span className="bento-tag" key={i}>{tech}</span>
              ))}
              {project.techStack.length > 8 && (
                <span className="bento-tag bento-tag--more">
                  +{project.techStack.length - 8} more
                </span>
              )}
            </div>
          )}

          {project.impact && (
            <p className="bento-impact">{project.impact}</p>
          )}

          {project.footerLink && project.footerLink.length > 0 && (
            <div className="bento-links">
              {project.footerLink.map((link, i) => (
                <a
                  key={i}
                  href={link.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="bento-link"
                  aria-label={`${link.name} for ${project.projectName} (opens in new tab)`}
                >
                  {link.name} ↗
                </a>
              ))}
            </div>
          )}
        </div>

        {/* RIGHT: image carousel */}
        <div className="bento-card--featured__media">
          <ProjectImageCarousel
            images={project.images}
            projectName={project.projectName}
            onImageClick={onImageClick}
          />
        </div>
      </div>
    </article>
  );
}

/* ─── Standard card (TrackBot, RupeeIQ) — vertical stack ───────────── */
function StandardCard({ project, isDark, onImageClick }) {
  const isTrackBot = project.projectName.includes("TrackBot");
  
  return (
    <article className="bento-card bento-card--standard" aria-label={`Project: ${project.projectName}`}>
      <div className="bento-card--standard__media">
        <ProjectImageCarousel
          images={project.images}
          projectName={project.projectName}
          onImageClick={onImageClick}
        />
      </div>
      <div className="bento-card--standard__content">
        <h3 className="bento-project-title bento-project-title--sm">
          {project.projectName}
        </h3>
        {project.problem && (
          <p className="bento-problem">{project.problem}</p>
        )}
        
        {isTrackBot && (
          <div className="bento-flow-wrapper" style={{ margin: "10px 0" }}>
            <TrackBotFlow isDark={isDark} />
          </div>
        )}

        {project.techStack && project.techStack.length > 0 && (
          <div className="bento-tags" aria-label="Tech stack">
            {project.techStack.slice(0, 5).map((tech, i) => (
              <span className="bento-tag" key={i}>{tech}</span>
            ))}
          </div>
        )}
        {project.impact && (
          <p className="bento-impact">{project.impact}</p>
        )}
        {project.footerLink && project.footerLink.length > 0 && (
          <div className="bento-links bento-links--mt-auto">
            {project.footerLink.map((link, i) => (
              <a
                key={i}
                href={link.url}
                target="_blank"
                rel="noopener noreferrer"
                className="bento-link"
                aria-label={`${link.name} for ${project.projectName} (opens in new tab)`}
              >
                {link.name} ↗
              </a>
            ))}
          </div>
        )}
      </div>
    </article>
  );
}

/* ─── CTA card — view all projects ─────────────────────────────────── */
function CTACard({ project }) {
  const url   = project?.footerLink?.[0]?.url  ?? "https://github.com/vishvrajdev";
  const label = project?.footerLink?.[0]?.name ?? "View all projects on GitHub";
  return (
    <article className="bento-card bento-card--cta" aria-label="View all projects">
      <a
        href={url}
        target="_blank"
        rel="noopener noreferrer"
        className="bento-card--cta__link"
        aria-label="View all projects on GitHub (opens in new tab)"
      >
        <span className="bento-card--cta__arrow" aria-hidden="true">⟶</span>
        <span className="bento-card--cta__label">{label}</span>
      </a>
    </article>
  );
}

/* ─── Root export ───────────────────────────────────────────────────── */
export default function StartupProject({ bigProjects = portfolioBigProjects } = {}) {
  const { isDark } = useContext(StyleContext);
  const [lightboxImage, setLightboxImage] = useState(null);

  const currentBigProjects = bigProjects || portfolioBigProjects;
  if (!currentBigProjects || !Array.isArray(currentBigProjects.projects)) return null;

  const featured  = currentBigProjects.projects.find(p => p.featured === true);
  const standards = currentBigProjects.projects.filter(p => !p.featured && !p.isCTA);
  const cta       = currentBigProjects.projects.find(p => p.isCTA === true);

  return (
    <section className="bento-section" id="projects" aria-labelledby="projects-heading">
      {currentBigProjects.title && (
        <h2 className="bento-section__title" id="projects-heading">
          {currentBigProjects.title}
        </h2>
      )}
      {currentBigProjects.subtitle && (
        <p className="bento-section__subtitle">{currentBigProjects.subtitle}</p>
      )}

      <div className="bento-grid">
        {/* Row 1: Featured card — full width */}
        {featured && <FeaturedCard project={featured} onImageClick={setLightboxImage} />}

        {/* Row 2: Standard cards + CTA — equal columns */}
        {(standards.length > 0 || cta) && (
          <div className="bento-row">
            {standards.map((project, i) => (
              <StandardCard 
                key={project.projectName ?? i} 
                project={project} 
                isDark={isDark} 
                onImageClick={setLightboxImage}
              />
            ))}
            {cta && <CTACard project={cta} />}
          </div>
        )}
      </div>

      {/* Glassmorphic Lightbox modal overlay */}
      {lightboxImage && (
        <div 
          className="bento-lightbox" 
          onClick={() => setLightboxImage(null)} 
          role="dialog" 
          aria-modal="true"
        >
          <div className="bento-lightbox__content" onClick={e => e.stopPropagation()}>
            <button className="bento-lightbox__close" onClick={() => setLightboxImage(null)}>
              <i className="fas fa-times"></i>
            </button>
            <img src={lightboxImage.src} alt={lightboxImage.alt} className="bento-lightbox__img" />
            {lightboxImage.alt && <p className="bento-lightbox__caption">{lightboxImage.alt}</p>}
          </div>
        </div>
      )}
    </section>
  );
}
