import React, { useContext } from "react";
import "./Recommendation.scss";
import { recommendationSection } from "../../portfolio";
import { Fade } from "react-reveal";
import StyleContext from "../../contexts/StyleContext";

export default function Recommendation() {
  const { isDark } = useContext(StyleContext);

  if (!recommendationSection || !recommendationSection.display) {
    return null;
  }

  return (
    <Fade bottom duration={1000} distance="20px">
      <section className="recommendation-section" id="recommendation" aria-labelledby="recommendation-heading">
        <div className="recommendation-container">
          <h1 className={isDark ? "dark-mode recommendation-heading" : "recommendation-heading"} id="recommendation-heading">
            {recommendationSection.title}
          </h1>
          <p className={isDark ? "dark-mode recommendation-subtitle" : "recommendation-subtitle"}>
            {recommendationSection.subtitle}
          </p>

          <div className="recommendation-cards-wrapper">
            {recommendationSection.recommendations.map((rec, i) => (
              <div 
                key={i} 
                className={isDark ? "dark-mode recommendation-card card-glow hover-tilt" : "recommendation-card card-glow hover-tilt"}
              >
                <div className="recommendation-quote-icon top">
                  <i className="fas fa-quote-left"></i>
                </div>
                
                <p className={isDark ? "dark-mode recommendation-text" : "recommendation-text"}>
                  {rec.text}
                </p>

                <div className="recommendation-quote-icon bottom">
                  <i className="fas fa-quote-right"></i>
                </div>

                <div className="recommendation-author-block">
                  <div className="recommendation-avatar">
                    <img src={rec.avatar} alt={`${rec.company} Logo`} />
                  </div>
                  <div className="recommendation-author-details">
                    <h4 className={isDark ? "dark-mode author-name" : "author-name"}>
                      {rec.author}
                    </h4>
                    <p className="author-meta">
                      {rec.role} &bull; <strong className="author-company">{rec.company}</strong>
                    </p>
                  </div>
                  {rec.viewLink && (
                    <div className="recommendation-action">
                      <a 
                        href={rec.viewLink} 
                        target="_blank" 
                        rel="noopener noreferrer" 
                        className="recommendation-btn"
                        aria-label="View Recommendation Letter (opens in new tab)"
                      >
                        <i className="fas fa-file-alt"></i> View Letter
                      </a>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>
    </Fade>
  );
}
