import React, {useContext} from "react";
import "./WorkExperience.scss";
import ExperienceCard from "../../components/experienceCard/ExperienceCard";
import {workExperiences} from "../../portfolio";
import {Fade} from "react-reveal";
import StyleContext from "../../contexts/StyleContext";

export default function WorkExperience() {
  const {isDark} = useContext(StyleContext);
  if (workExperiences.display) {
    return (
      <div id="experience">
        <Fade bottom duration={1000} distance="20px">
          <div className="experience-container" id="workExperience">
            <h1 className="experience-heading">Experience</h1>
            <div className="experience-main-content">
              <div className="experience-metrics-div">
                <div className={isDark ? "dark-mode metric-card hover-tilt card-glow" : "metric-card hover-tilt card-glow"}>
                  <h3 className="metric-value">10k+</h3>
                  <p className="metric-label">Rows of Structured Data Analyzed</p>
                </div>
                <div className={isDark ? "dark-mode metric-card hover-tilt card-glow" : "metric-card hover-tilt card-glow"}>
                  <h3 className="metric-value">78%</h3>
                  <p className="metric-label">Model Classification Accuracy</p>
                </div>
                <div className={isDark ? "dark-mode metric-card hover-tilt card-glow" : "metric-card hover-tilt card-glow"}>
                  <h3 className="metric-value">60%</h3>
                  <p className="metric-label">Preprocessing Time Saved via Pipelines</p>
                </div>
                <div className={isDark ? "dark-mode metric-card hover-tilt card-glow" : "metric-card hover-tilt card-glow"}>
                  <h3 className="metric-value">~15%</h3>
                  <p className="metric-label">Improvement in Model F1-Score</p>
                </div>
              </div>
              <div className="experience-cards-div">
                {workExperiences.experience.map((card, i) => {
                  return (
                    <ExperienceCard
                      key={i}
                      isDark={isDark}
                      cardInfo={{
                        company: card.company,
                        desc: card.desc,
                        date: card.date,
                        companylogo: card.companylogo,
                        role: card.role,
                        descBullets: card.descBullets,
                        color: card.color
                      }}
                    />
                  );
                })}
              </div>
            </div>
          </div>
        </Fade>
      </div>
    );
  }
  return null;
}
