import React from "react";
import "./NeuralNetworkSVG.scss";

// Node positions for a 4-layer neural network
const layers = [
  // Input layer (4 nodes)
  [
    { x: 80, y: 60 },
    { x: 80, y: 140 },
    { x: 80, y: 220 },
    { x: 80, y: 300 },
  ],
  // Hidden layer 1 (5 nodes)
  [
    { x: 200, y: 30 },
    { x: 200, y: 100 },
    { x: 200, y: 170 },
    { x: 200, y: 240 },
    { x: 200, y: 310 },
  ],
  // Hidden layer 2 (3 nodes)
  [
    { x: 320, y: 90 },
    { x: 320, y: 180 },
    { x: 320, y: 270 },
  ],
  // Output layer (1 node)
  [{ x: 440, y: 180 }],
];

function NeuralNetworkSVG() {
  // Build connections between adjacent layers
  const connections = [];
  for (let l = 0; l < layers.length - 1; l++) {
    for (let i = 0; i < layers[l].length; i++) {
      for (let j = 0; j < layers[l + 1].length; j++) {
        connections.push({
          x1: layers[l][i].x,
          y1: layers[l][i].y,
          x2: layers[l + 1][j].x,
          y2: layers[l + 1][j].y,
          delay: (l * 0.4 + i * 0.1 + j * 0.08).toFixed(2),
        });
      }
    }
  }

  return (
    <div className="neural-network-container">
      <svg
        viewBox="0 0 520 360"
        xmlns="http://www.w3.org/2000/svg"
        className="neural-network-svg"
      >
        <defs>
          {/* Glow filter for nodes */}
          <filter id="node-glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="4" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>

          {/* Gradient for connections */}
          <linearGradient id="conn-gradient" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="rgba(168, 85, 247, 0.15)" />
            <stop offset="50%" stopColor="rgba(168, 85, 247, 0.4)" />
            <stop offset="100%" stopColor="rgba(168, 85, 247, 0.15)" />
          </linearGradient>

          {/* Radial gradient for node fill */}
          <radialGradient id="node-fill" cx="40%" cy="35%">
            <stop offset="0%" stopColor="#c084fc" />
            <stop offset="100%" stopColor="#a855f7" />
          </radialGradient>

          {/* Output node special gradient */}
          <radialGradient id="output-fill" cx="40%" cy="35%">
            <stop offset="0%" stopColor="#e9d5ff" />
            <stop offset="100%" stopColor="#a855f7" />
          </radialGradient>
        </defs>

        {/* Connections */}
        {connections.map((conn, idx) => (
          <line
            key={`conn-${idx}`}
            className="nn-connection"
            x1={conn.x1}
            y1={conn.y1}
            x2={conn.x2}
            y2={conn.y2}
            stroke="url(#conn-gradient)"
            strokeWidth="1.2"
            style={{ animationDelay: `${conn.delay}s` }}
          />
        ))}

        {/* Nodes */}
        {layers.map((layer, layerIdx) =>
          layer.map((node, nodeIdx) => {
            const isOutput = layerIdx === layers.length - 1;
            const radius = isOutput ? 14 : 10;
            const delay = (layerIdx * 0.5 + nodeIdx * 0.15).toFixed(2);

            return (
              <g key={`node-${layerIdx}-${nodeIdx}`}>
                {/* Outer glow ring */}
                <circle
                  className="nn-node-glow"
                  cx={node.x}
                  cy={node.y}
                  r={radius + 6}
                  fill="none"
                  stroke="rgba(168, 85, 247, 0.15)"
                  strokeWidth="1"
                  style={{ animationDelay: `${delay}s` }}
                />
                {/* Main node */}
                <circle
                  className="nn-node"
                  cx={node.x}
                  cy={node.y}
                  r={radius}
                  fill={isOutput ? "url(#output-fill)" : "url(#node-fill)"}
                  filter="url(#node-glow)"
                  style={{ animationDelay: `${delay}s` }}
                />
                {/* Center dot highlight */}
                <circle
                  cx={node.x - 2}
                  cy={node.y - 2}
                  r={radius * 0.25}
                  fill="rgba(255,255,255,0.4)"
                />
              </g>
            );
          })
        )}

        {/* Floating data particles along some connections */}
        {[0, 5, 12, 22, 30].map((connIdx) => {
          if (connIdx >= connections.length) return null;
          const conn = connections[connIdx];
          return (
            <circle
              key={`particle-${connIdx}`}
              className="nn-particle"
              r="2.5"
              fill="#c084fc"
              style={{ animationDelay: `${connIdx * 0.3}s` }}
            >
              <animateMotion
                dur={`${2 + connIdx * 0.2}s`}
                repeatCount="indefinite"
                path={`M${conn.x1},${conn.y1} L${conn.x2},${conn.y2}`}
              />
            </circle>
          );
        })}
      </svg>
    </div>
  );
}

export default NeuralNetworkSVG;
